function wutm_hp_slide_row(int $i,array $s){?><div class="wutm-hp-slide"><button type="button" class="button wutm-hp-remove">刪除</button><h3>輪播圖片</h3><div class="wutm-hp-field">電腦版圖片<div class="wutm-hp-slide-grid"><input name="wutm_homepage_products[slides][<?php echo $i;?>][desktop]" value="<?php echo esc_attr($s['desktop']??'');?>"><button type="button" class="button wutm-hp-upload">媒體庫</button></div></div><div class="wutm-hp-field">手機版圖片（選填）<div class="wutm-hp-slide-grid"><input name="wutm_homepage_products[slides][<?php echo $i;?>][mobile]" value="<?php echo esc_attr($s['mobile']??'');?>"><button type="button" class="button wutm-hp-upload">媒體庫</button></div></div><div class="wutm-hp-field">連結（選填）<input type="url" name="wutm_homepage_products[slides][<?php echo $i;?>][link]" value="<?php echo esc_attr($s['link']??'');?>"></div></div><?php }

function wutm_hp_product_query(array $o,int $cols,int $rows,int $page):WP_Query{
    $args=['post_type'=>'product','post_status'=>'publish','ignore_sticky_posts'=>true,'posts_per_page'=>$cols*$rows,'paged'=>max(1,$page),'orderby'=>'date','order'=>'DESC','no_found_rows'=>false];
    if(function_exists('WC')&&WC()->query){$args['meta_query']=WC()->query->get_meta_query();$args['tax_query']=WC()->query->get_tax_query();}
    switch($o['product_type']){
        case'featured':$terms=wc_get_product_visibility_term_ids();$args['tax_query'][]=['taxonomy'=>'product_visibility','field'=>'term_taxonomy_id','terms'=>[$terms['featured']],'operator'=>'IN'];break;
        case'sale':$args['post__in']=array_merge([0],wc_get_product_ids_on_sale());break;
        case'best_selling':$args['meta_key']='total_sales';$args['orderby']='meta_value_num';break;
        case'category':if($o['category'])$args['tax_query'][]=['taxonomy'=>'product_cat','field'=>'slug','terms'=>[$o['category']]];break;
        case'specific':$ids=array_values(array_filter(array_map('absint',explode(',',$o['product_ids']))));$args['post__in']=$ids?:[0];$args['orderby']='post__in';break;
    }
    return new WP_Query($args);
}
function wutm_hp_products_html(WP_Query $query,int $cols):string{
    ob_start();
    if($query->have_posts()){
        wc_set_loop_prop('columns',$cols);wc_set_loop_prop('total',(int)$query->found_posts);wc_set_loop_prop('per_page',(int)$query->get('posts_per_page'));wc_set_loop_prop('current_page',max(1,(int)$query->get('paged')));wc_set_loop_prop('is_paginated',true);
        woocommerce_product_loop_start();
        while($query->have_posts()){$query->the_post();wc_get_template_part('content','product');}
        woocommerce_product_loop_end();
    }else echo '<p class="woocommerce-info">目前沒有可顯示的商品。</p>';
    wp_reset_postdata();wc_reset_loop();
    return (string)ob_get_clean();
}
function wutm_hp_ajax_products():void{
    $cols=max(1,min(6,absint($_POST['columns']??4)));$rows=max(1,min(20,absint($_POST['rows']??3)));$page=max(1,absint($_POST['product_page']??1));
    $query=wutm_hp_product_query(wutm_hp_options(),$cols,$rows,$page);
    wp_send_json_success(['html'=>wutm_hp_products_html($query,$cols),'page'=>$page,'max_pages'=>max(1,(int)$query->max_num_pages)]);
}
add_action('wp_ajax_wutm_hp_products','wutm_hp_ajax_products');
add_action('wp_ajax_nopriv_wutm_hp_products','wutm_hp_ajax_products');

function wutm_hp_shortcode($atts):string{
