av class="wutm-hp-pagination" aria-label="商品分頁"><span class="wutm-hp-page-numbers"></span></nav><?php endif;?></div><?php endif;?></div>
    <style>#<?php echo esc_attr($uid);?>{width:100%;max-width:var(--wutm-hp-width);margin:auto;padding:0 15px;box-sizing:border-box}#<?php echo esc_attr($uid);?> .wutm-hp-slider{position:relative;display:grid;grid-template-areas:"slide";overflow:hidden;border-radius:12px;margin-bottom:28px;background:#f4f5f7}#<?php echo esc_attr($uid);?> .wutm-hp-frame{grid-area:slide;opacity:0;visibility:hidden;transition:opacity .65s}#<?php echo esc_attr($uid);?> .wutm-hp-frame.is-active{opacity:1;visibility:visible}#<?php echo esc_attr($uid);?> .wutm-hp-frame img{display:block;width:100%;height:auto}#<?php echo esc_attr($uid);?> .wutm-hp-prev,#<?php echo esc_attr($uid);?> .wutm-hp-next{position:absolute;z-index:2;top:50%;width:42px;height:42px;border:0;border-radius:50%;background:#0008;color:#fff;font-size:28px;transform:translateY(-50%);cursor:pointer}#<?php echo esc_attr($uid);?> .wutm-hp-prev{left:14px}#<?php echo esc_attr($uid);?> .wutm-hp-next{right:14px}#<?php echo esc_attr($uid);?> .wutm-hp-middle{margin:28px 0}#<?php echo esc_attr($uid);?> .products{display:grid!important;grid-template-columns:repeat(var(--wutm-hp-cols),minmax(0,1fr))!important;gap:20px!important}#<?php echo esc_attr($uid);?> .products .product{width:auto!important;margin:0!important}#<?php echo esc_attr($uid);?> .hide-cart .add_to_cart_button,#<?php echo esc_attr($uid);?> .hide-cart .ct-cart-actions{display:none!important}#<?php echo esc_attr($uid);?> .wutm-hp-more{text-align:center;margin:35px 0}#<?php echo esc_attr($uid);?> .wutm-hp-more>a,#<?php echo esc_attr($uid);?> .wutm-hp-more>.wutm-hp-more-button{display:inline-block;padding:12px 28px;border:0;border-radius:8px;background:var(--wutm-hp-accent);color:var(--wutm-hp-button-text);text-decoration:none;cursor:pointer}#<?php echo esc_attr($uid);?> .wutm-hp-more-button:disabled{opacity:.55;cursor:wait}#<?php echo esc_attr($uid);?> .wutm-hp-pagination{display:flex;justify-content:center;align-items:center}#<?php echo esc_attr($uid);?> .wutm-hp-page-numbers{display:flex;gap:8px;align-items:center}#<?php echo esc_attr($uid);?> .wutm-hp-pagination button{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;margin:0;padding:0;border:1px solid #d8dadd;border-radius:50%;background:#fff;color:#333;font-size:14px;font-weight:600;line-height:1;cursor:pointer}#<?php echo esc_attr($uid);?> .wutm-hp-pagination button:hover{border-color:var(--wutm-hp-accent);color:var(--wutm-hp-accent)}#<?php echo esc_attr($uid);?> .wutm-hp-pagination button.is-current,#<?php echo esc_attr($uid);?> .wutm-hp-pagination button.is-current:disabled{border-color:var(--wutm-hp-accent);background:var(--wutm-hp-accent);color:var(--wutm-hp-button-text);opacity:1;cursor:default}#<?php echo esc_attr($uid);?> .wutm-hp-page-numbers>span{color:#888}@media(max-width:900px){#<?php echo esc_attr($uid);?> .products{grid-template-columns:repeat(2,minmax(0,1fr))!important}}</style>
    <script>(function(){const r=document.getElementById(<?php echo wp_json_encode($uid);?>);if(!r)return;const s=r.querySelector('.wutm-hp-slider');if(s){const a=[...s.querySelectorAll('.wutm-hp-frame')];if(a.length>1){let i=0,t;const show=n=>{a[i].classList.remove('is-active');i=(n+a.length)%a.length;a[i].classList.add('is-active')};const start=()=>{if(s.dataset.autoplay==='1'&&!t)t=setInterval(()=>show(i+1),parseInt(s.dataset.speed,10)||5000)};s.querySelector('.wutm-hp-next').onclick=()=>{show(i+1);clearInterval(t);t=null;start()};s.querySelector('.wutm-hp-prev').onclick=()=>{show(i-1);clearInterval(t);t=null;start()};s.addEventListener('mouseenter',()=>{clearInterval(t);t=null});s.addEventListener('mouseleave',start);start()}}const more=r.querySelector('.wutm-hp-more');if(!more||more.dataset.mode==='link')return;let page=1,pages=parseInt(r.dataset.pages,10)||1,busy=false;const products=r.querySelector('.wutm-hp-products'),load=more.querySelector('.wutm-hp-more-button'),nav=more.querySelector('.wutm-hp-pagination');function draw(){if(!nav)return;const box=nav.querySelector('.wutm-hp-page-numbers'),wanted=[];for(let n=1;n<=pages;n++)if(n===1||n===pages||Math.abs(n-page)<=2)wanted.push(n);box.innerHTML='';let last=0;wanted.forEach(n=>{if(last&&n-last>1)box.insertAdjacentHTML('beforeend','<span>…</span>');const b=document.createElement('button');b.type='button';b.dataset.page=String(n);b.textContent=String(n);if(n===page){b.className='is-current';b.disabled=true}box.appendChild(b);last=n})}async function fetchPage(next,append){if(busy||next<1||next>pages)return;busy=true;if(load)load.disabled=true;const data=new URLSearchParams({action:'wutm_hp_products',columns:r.dataset.columns,rows:r.dataset.rows,product_page:String(next)});try{const res=await fetch(<?php echo wp_json_encode(admin_url('admin-ajax.php'));?>,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data.toString()}),json=await res.json();if(!json.success)throw new Error('request');if(append){const temp=document.createElement('div');temp.innerHTML=json.data.html;const current=products.querySelector('.products'),incoming=temp.querySelector('.products');if(current&&incoming)[...incoming.children].forEach(el=>current.appendChild(el));else products.innerHTML=json.data.html}else{products.innerHTML=json.data.html;products.scrollIntoView({behavior:'smooth',block:'start'})}page=parseInt(json.data.page,10)||next;pages=parseInt(json.data.max_pages,10)||pages;r.dataset.page=String(page);r.dataset.pages=String(pages);if(load&&page>=pages)more.remove();draw();if(window.jQuery)jQuery(document.body).trigger('wutm_hp_products_loaded',[r])}catch(e){if(load)load.textContent='載入失敗，請再試一次'}finally{busy=false;if(load&&document.body.contains(load)&&page<pages)load.disabled=false;draw()}}if(load)load.addEventListener('click',()=>fetchPage(page+1,true));if(nav)nav.addEventListener('click',e=>{const b=e.target.closest('button[data-page]');if(b)fetchPage(parseInt(b.dataset.page,10),false)});draw()})();</script><?php return (string)ob_get_clean();
}
